update public.products set description='Minu Chicken Franks are frozen processed chicken sausages supplied as a 340 g pack containing 10 franks, suitable for hot dogs, sandwiches, breakfast meals and other quick cooked preparations.', handling_protocols=array['Keep the pack frozen until needed and follow the preparation instructions printed on the manufacturer package.','Thaw in the refrigerator rather than on a kitchen counter.','Use clean utensils and heat or cook according to the package directions before serving.']::text[], storage_tips=array['Follow the storage temperature and best-before or use-by date printed on the Minu package; the manufacturer label overrides generic guidance.','Keep frozen at about -18°C or below until required.','Once safely thawed and opened, refrigerate and use within about 7 days unless the package specifies a shorter period.']::text[] where name='Minu Chicken Franks' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
